$(cat graphify-out/.graphify_python 2>/dev/null || echo python3) -c "
import json, collections
data = json.load(open('graphify-out/graph.json'))
nodes = {n['id']: n for n in data['nodes']}

func_ids_internal = {nid for nid, n in nodes.items() if n.get('source_file','').startswith('internal/') and n.get('label','').endswith('()')}

call_rels = {'calls','indirect_call'}
in_counts = collections.Counter()
callers = collections.defaultdict(set)
for e in data['links']:
    if e['relation'] in call_rels:
        s, t = e['source'], e['target']
        if t in func_ids_internal:
            in_counts[t]+=1
            callers[t].add(s)
        if s in func_ids_internal and data['directed']==False:
            pass

top = in_counts.most_common(15)
for tid, c in top:
    n = nodes[tid]
    print(c, len(callers[tid]), n['label'], n['source_file'], n['source_location'])
"

